"""小红书数据类型定义，对应 Go types.go。"""

from __future__ import annotations

from dataclasses import dataclass, field


def _extract_publish_time_from_id(note_id: str) -> int:
    """从小红书 note ID（MongoDB ObjectId 格式）提取精确发布时间戳。

    MongoDB ObjectId 的前 4 字节（8 个 hex 字符）是 Unix 秒时间戳，
    这是最精确的发布时间来源，无需依赖 cornerTagInfo 文字解析。

    Args:
        note_id: 小红书帖子 ID，如 "69a56e1b000000000d00ac3e"。

    Returns:
        Unix 秒时间戳，解析失败返回 0。
    """
    if not note_id or len(note_id) < 8:
        return 0
    try:
        return int(note_id[:8], 16)
    except ValueError:
        return 0

# ========== Feed 列表 ==========


@dataclass
class ImageInfo:
    image_scene: str = ""
    url: str = ""

    @classmethod
    def from_dict(cls, d: dict) -> ImageInfo:
        return cls(
            image_scene=d.get("imageScene", ""),
            url=d.get("url", ""),
        )


@dataclass
class VideoCapability:
